// Bounded Worker ownership helpers. The map owns string keys and shapes;
// inserting a result must not replace an existing owner.
static bool ContainsOwnedNameV2(const char* name) { return shapes.find(std::string(name)) != shapes.end(); }
static bool InsertOwnedNameV2(const char* name, const TopoDS_Shape& shape) { return shapes.emplace(std::string(name),shape).second; }
static bool ReleaseOwnedNameV2(const char* name) { return shapes.erase(std::string(name)) == 1; }
static size_t OwnedNameCountV2() { return shapes.size(); }

