void ResearchFourCornerCut(const char* parentName, const char* t0, const char* t1, const char* t2, const char* t3, const char* resultName) {
  try {
    const char* names[] = {parentName,t0,t1,t2,t3,resultName};
    for(int i=0;i<6;i++){if(!names[i] || !*names[i] || strlen(names[i])>64)throw std::runtime_error("invalid name");for(int j=0;j<i;j++)if(!strcmp(names[i],names[j]))throw std::runtime_error("duplicate name");}
    TopoDS_Shape container=DBRep::Get(parentName);if(container.IsNull() || container.ShapeType()!=TopAbs_COMPOUND || !DBRep::Get(resultName).IsNull())throw std::runtime_error("invalid parent or output");
    TopoDS_Iterator children(container);if(!children.More())throw std::runtime_error("empty parent");TopoDS_Shape parent=children.Value();children.Next();if(children.More() || parent.ShapeType()!=TopAbs_SOLID || !BRepCheck_Analyzer(parent).IsValid())throw std::runtime_error("parent not one valid direct solid");
    TopTools_ListOfShape arguments,tools;arguments.Append(parent);TopoDS_Shape toolShapes[4];
    for(int i=1;i<=4;i++){TopoDS_Shape tool=DBRep::Get(names[i]);if(tool.IsNull() || tool.ShapeType()!=TopAbs_SOLID || !BRepCheck_Analyzer(tool).IsValid())throw std::runtime_error("invalid tool");if(tool.IsSame(parent))throw std::runtime_error("tool aliases parent");for(int j=0;j<i-1;j++)if(tool.IsSame(toolShapes[j]))throw std::runtime_error("duplicate tool shape");toolShapes[i-1]=tool;tools.Append(tool);}
    BRepAlgoAPI_Cut operation;operation.SetArguments(arguments);operation.SetTools(tools);operation.SetNonDestructive(Standard_True);operation.SetFuzzyValue(1e-7);operation.SetToFillHistory(Standard_True);operation.Build();
    if(!operation.IsDone() || operation.HasErrors() || operation.Shape().IsNull())throw std::runtime_error("cut failed");
    TopoDS_Shape output=operation.Shape();TopoDS_Shape solid=output;
    if(output.ShapeType()==TopAbs_COMPOUND){TopoDS_Iterator it(output);if(!it.More())throw std::runtime_error("empty output");solid=it.Value();it.Next();if(it.More())throw std::runtime_error("multiple output children");}
    if(solid.ShapeType()!=TopAbs_SOLID || !BRepCheck_Analyzer(solid).IsValid())throw std::runtime_error("invalid output solid");
    GProp_GProps before,after;BRepGProp::VolumeProperties(parent,before);BRepGProp::VolumeProperties(solid,after);
    if(!std::isfinite(before.Mass()) || !std::isfinite(after.Mass()) || after.Mass()<=0 || !(before.Mass()-after.Mass()>std::max(1e-7,std::abs(before.Mass())*1e-12)))throw std::runtime_error("no positive material removal");
    const std::string result=e0::research::fourCornerTopology(parent,toolShapes,operation.Shape(),operation.History());
    DBRep::Set(resultName,operation.Shape());EM_ASM_({ __OCI_EXCHANGE(UTF8ToString($0)); }, result.c_str());
  } catch (...) { EM_ASM_({ __OCI_EXCHANGE("{\"version\":1,\"error\":\"FOUR_CUT_FAILED\"}"); }); }
}

