void PerformDrilledCutV1(const char* parentName, const char* toolName, const char* resultName) {
  try {
    if (!parentName || !toolName || !resultName || strlen(parentName)>64 || strlen(toolName)>64 || strlen(resultName)>64 || !strlen(resultName) || !strcmp(parentName,resultName) || !strcmp(toolName,resultName)) throw std::runtime_error("invalid names");
    TopoDS_Shape parent=DBRep::Get(parentName),tool=DBRep::Get(toolName);
    if(parent.IsNull() || tool.IsNull() || parent.ShapeType()!=TopAbs_SOLID || tool.ShapeType()!=TopAbs_SOLID || !DBRep::Get(resultName).IsNull()) throw std::runtime_error("invalid operands or result exists");
    BRepAlgoAPI_Cut operation;TopTools_ListOfShape arguments,tools;arguments.Append(parent);tools.Append(tool);
    operation.SetArguments(arguments);operation.SetTools(tools);operation.SetNonDestructive(Standard_True);operation.SetFuzzyValue(1e-7);operation.SetToFillHistory(Standard_True);operation.Build();
    if(!operation.IsDone() || operation.HasErrors() || operation.Shape().IsNull()) throw std::runtime_error("cut failed");
    const std::string result=e0::research::drilledTopology(parent,tool,operation.Shape(),operation.History());
    DBRep::Set(resultName,operation.Shape());
    EM_ASM_({ __OCI_EXCHANGE(UTF8ToString($0)); }, result.c_str());
  } catch (...) { EM_ASM_({ __OCI_EXCHANGE("{\"version\":1,\"error\":\"DRILLED_CUT_FAILED\"}"); }); }
